<template><view class="page"><view class="nav"><text @tap="back" class="cuIcon-back"/>我的投稿<text/></view><view class="tabs"><text v-for="x in tabs" :key="x.value" :class="{active:tab===x.value}" @tap="tab=x.value">{{x.label}}</text></view><view v-for="item in items" :key="item.id" class="item" @tap="open(item)"><view><text class="status">{{statusLabel(item.status)}}</text><text class="title">{{item.title}}</text><text class="meta">{{item.journalName||'见字'}} · {{displayDate(item.modified||item.created)}}</text></view><text class="cuIcon-right"/></view><view v-if="!loading&&!items.length" class="empty">还没有投稿记录 · <text @tap="create">去写一篇</text></view><view v-if="loading" class="empty">正在读取投稿</view></view></template>
<script>
import { localStorage } from '../../js_sdk/mp-storage/mp-storage/index.js'
export default {data(){return {tab:'all',items:[],loading:true,tabs:[{label:'全部',value:'all'},{label:'审核中',value:'submitted'},{label:'已发布',value:'published'},{label:'已退回',value:'rejected'}]}},onLoad(){this.load()},watch:{tab(){this.load()}},methods:{token(){try{return JSON.parse(localStorage.getItem('userinfo')||'{}').token||''}catch(e){return ''}},back(){uni.navigateBack({delta:1})},create(){uni.navigateTo({url:'/pages/journal/post'})},load(){this.loading=true;let d={token:this.token(),page:1,limit:50};if(this.tab!=='all')d.status=this.tab;this.$Net.request({url:this.$API.journalMyArticles(),data:d,method:'get',dataType:'json',success:r=>{this.items=r.data&&r.data.code===1&&Array.isArray(r.data.data)?r.data.data:[];this.loading=false},fail:()=>{this.items=[];this.loading=false}})},statusLabel(v){return {submitted:'审核中',published:'已发布',rejected:'已退回',draft:'草稿',hidden:'已隐藏'}[v]||'草稿'},open(x){if(x&&x.id)uni.navigateTo({url:'/pages/journal/article?id='+x.id})},displayDate(v){let d=new Date(Number(v)>10000000000?Number(v):Number(v)*1000);return isNaN(d.getTime())?'':d.getFullYear()+'.'+String(d.getMonth()+1).padStart(2,'0')+'.'+String(d.getDate()).padStart(2,'0')}}}
</script>
<style scoped>.page{min-height:100vh;background:#f4f1eb;color:#1b2c27}.nav{display:flex;justify-content:space-between;padding:calc(22px + env(safe-area-inset-top)) 24px 17px;font:21px Georgia,serif}.tabs{display:flex;gap:22px;padding:12px 24px;border-bottom:1px solid #d8dfd9;color:#83928b;font-size:13px}.tabs .active{color:#294d40;border-bottom:2px solid #a9744e;padding-bottom:9px}.item{display:flex;justify-content:space-between;gap:16px;padding:22px 24px;border-bottom:1px solid #d8dfd9}.status{display:inline-block;padding:4px 8px;border-radius:12px;background:#e2ebe4;color:#4b7565;font-size:10px}.title{display:block;margin-top:10px;font:22px Georgia,serif;color:#294d40}.meta{display:block;margin-top:8px;font-size:11px;color:#8c9a94}.empty{text-align:center;padding:100px 24px;color:#8c9a94}.empty text{color:#527869}
</style>
